lowering_checkpoint_status_v1 plan_lowering_resumption_v1(const std::vector<lowering_checkpoint_v1>&s,const std::vector<lowering_checkpoint_v1>&x,lowering_resumption_plan_v1*out,std::string*e)noexcept{constexpr auto count=static_cast<std::size_t>(ceir_facet_v1::count);if(!out||s.size()!=count||x.size()!=count)return fail(lowering_checkpoint_status_v1::missing_facet,e,"all CEIR facets required");out->reusable.fill(false);lowering_checkpoint_status_v1 reason=lowering_checkpoint_status_v1::valid;std::size_t first=count;for(std::size_t i=0;i<count;++i){if(static_cast<std::size_t>(s[i].facet)!=i||x[i].facet!=s[i].facet)return fail(lowering_checkpoint_status_v1::duplicate_facet,e,"facets must be unique and ordered");if(!valid(s[i].artifact)||!valid(s[i].content_hash)||!valid(x[i].content_hash))return fail(lowering_checkpoint_status_v1::invalid_identity,e,"artifact and hashes required");if(first==count){if(!(s[i].content_hash==x[i].content_hash)){first=i;reason=lowering_checkpoint_status_v1::content_corrupt;}else if(!(s[i].input_hash==x[i].input_hash)){first=i;reason=lowering_checkpoint_status_v1::input_changed;}else if(s[i].structure_epoch!=x[i].structure_epoch){first=i;reason=lowering_checkpoint_status_v1::epoch_changed;}else if(s[i].value_generation!=x[i].value_generation){first=i;reason=lowering_checkpoint_status_v1::generation_changed;}else out->reusable[i]=true;}}out->resume_at=static_cast<ceir_facet_v1>(first==count?count-1:first);if(e)e->clear();return reason;}
